import React, { useState } from 'react';
import './App.css'; // make sure this is imported if you have it separate

function App() {
  const [ingredients, setIngredients] = useState('');
  const [recipe, setRecipe] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [voiceUrl, setVoiceUrl] = useState('');
  const [videoUrl, setVideoUrl] = useState('');

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setRecipe('');
    setVoiceUrl('');
    setVideoUrl('');
    setLoading(true);

    if (!ingredients.trim()) {
      setError('Please enter some ingredients');
      setLoading(false);
      return;
    }

    try {
      const response = await fetch('/api/generate-recipe', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          ingredients: ingredients.split(',').map(i => i.trim()),
        }),
      });

      if (!response.ok) {
        throw new Error('Backend returned error.');
      }

      const data = await response.json();

      if (data.status === "success") {
        setRecipe(data.recipe);
        setVoiceUrl(data.voice_url);
        setVideoUrl(data.video_url);
      } else {
        throw new Error(data.error || "Unknown error");
      }

    } catch (err) {
      console.error(err);
      setError('Connection failed. Make sure Flask and Ollama are both running.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="app">
      <header>
        <h1>IntelliRecipe</h1>
        <p>Turn your ingredients into delicious meals</p>
      </header>

      <form onSubmit={handleSubmit}>
        <input
          placeholder="Enter ingredients (comma separated)"
          value={ingredients}
          onChange={(e) => setIngredients(e.target.value)}
        />
        <button type="submit" disabled={loading}>
          {loading ? 'Loading...' : 'Find Recipes'}
        </button>
      </form>

      {error && <p style={{ color: 'red' }}>{error}</p>}
      {recipe && (
        <div className="recipe-box">
          <h2>Recipe:</h2>
          <p>{recipe}</p>
        </div>
      )}

      {voiceUrl && (
        <div>
          <h3>Voice:</h3>
          <audio controls src={voiceUrl}></audio>
        </div>
      )}

      {videoUrl && (
        <div>
          <h3>Video:</h3>
          <video controls width="600" src={videoUrl}></video>
        </div>
      )}

      {/* ✅ ✅ ✅ Spinner overlay placed INSIDE the return */}
      {loading && (
        <div className="spinner-overlay">
          <div className="spinner"></div>
        </div>
      )}
    </div>
  );
}

export default App;
